// Two ways to catch scam job messages.
//  1. Rules: a person writes the rules. Clear and predictable, but only catches what the writer thought of.
//  2. Learning: the computer counts which words appear in scam and normal messages in the examples,
//     then uses those counts to judge a new message. It can notice patterns nobody wrote down.

export type Example = { text: string; spam: boolean };

export const startExamples: Example[] = [
  { text: 'Pay a registration fee of 2000 rupees to confirm your job offer today', spam: true },
  { text: 'Earn 5000 per day from home, guaranteed income, no experience needed', spam: true },
  { text: 'Urgent! Last chance, limited seats, send your bank account details now', spam: true },
  { text: 'You are selected. Share your OTP and Aadhaar number to receive the joining letter', spam: true },
  { text: 'Congratulations winner, claim your free laptop and job, pay the courier charge', spam: true },
  { text: 'Work from home and earn lakhs weekly, just pay a small security deposit first', spam: true },
  { text: 'Hurry, earn money fast with this simple task, guaranteed payment, join now', spam: true },
  { text: 'We would like to invite you for an interview on Monday at 10 am at our Pune office', spam: false },
  { text: 'Thank you for applying for the accountant role. Our team will review your resume', spam: false },
  { text: 'Please bring your certificates and one photo ID for the walk-in drive on Friday', spam: false },
  { text: 'Your application for warehouse supervisor has been shortlisted. Please confirm a time', spam: false },
  { text: 'The salary range for this role is 25000 to 30000 per month plus provident fund', spam: false },
  { text: 'Reminder: your video interview with the hiring manager starts tomorrow at 3 pm', spam: false },
  { text: 'We have received your resume and will contact you if your profile matches', spam: false },
];

const words = (text: string) => text.toLowerCase().match(/[a-z0-9]+/g) ?? [];

// ---------- 1. Rules ----------
export type Rule = { name: string; test: (text: string) => boolean };

export const RULES: Rule[] = [
  { name: 'asks you to pay first', test: (t) => /(registration|security|training|courier)\s+(fee|deposit|charge)|pay\s.*\b(fee|deposit)\b/i.test(t) },
  { name: 'promises easy money', test: (t) => /earn\s+\d+.*(per day|a day|daily|weekly)|guaranteed\s+(job|income|payment)/i.test(t) },
  { name: 'asks for private details', test: (t) => /\b(otp|aadhaar|bank account|card number|password)\b/i.test(t) },
  { name: 'pushes you to hurry', test: (t) => /\b(urgent|hurry|last chance|limited seats|act now)\b/i.test(t) },
];

export function ruleVerdict(text: string) {
  const hits = RULES.filter((r) => r.test(text)).map((r) => r.name);
  return { spam: hits.length > 0, hits };
}

// ---------- 2. Learning (naive Bayes) ----------
export class NaiveBayes {
  private counts = { spam: new Map<string, number>(), ham: new Map<string, number>() };
  private docs = { spam: 0, ham: 0 };
  private total = { spam: 0, ham: 0 };
  private vocab = new Set<string>();

  constructor(examples: Example[]) {
    for (const ex of examples) {
      const c = ex.spam ? 'spam' : 'ham';
      this.docs[c]++;
      for (const w of new Set(words(ex.text))) {
        this.counts[c].set(w, (this.counts[c].get(w) ?? 0) + 1);
        this.total[c]++;
        this.vocab.add(w);
      }
    }
  }

  // How much one word pushes towards spam (positive) or normal (negative), as a log ratio.
  weight(word: string) {
    const v = this.vocab.size || 1;
    const pSpam = ((this.counts.spam.get(word) ?? 0) + 1) / (this.total.spam + v); // +1 so unseen words never give zero
    const pHam = ((this.counts.ham.get(word) ?? 0) + 1) / (this.total.ham + v);
    return Math.log(pSpam / pHam);
  }

  classify(text: string) {
    const n = this.docs.spam + this.docs.ham;
    if (!n || !this.docs.spam || !this.docs.ham) return { spam: false, probSpam: 0.5, top: [] as { word: string; weight: number }[] };
    const uniq = [...new Set(words(text))].filter((w) => this.vocab.has(w));
    const prior = Math.log((this.docs.spam + 1) / (this.docs.ham + 1));
    const parts = uniq.map((word) => ({ word, weight: this.weight(word) }));
    const logOdds = prior + parts.reduce((s, p) => s + p.weight, 0);
    const probSpam = 1 / (1 + Math.exp(-logOdds)); // turn log-odds into a probability between 0 and 1
    const top = parts.filter((p) => Math.abs(p.weight) > 0.2).sort((a, b) => Math.abs(b.weight) - Math.abs(a.weight)).slice(0, 6);
    return { spam: probSpam >= 0.5, probSpam, top };
  }
}

import { Component, computed, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { NaiveBayes, ruleVerdict, startExamples, type Example } from '../lib/spam';

@Component({
  selector: 'app-spam',
  imports: [FormsModule],
  template: `
    <h1>Rules or learning?</h1>
    <p class="hint">Paste a job message. One checker uses rules a person wrote. The other learned from the examples below. Add your own examples and watch the learner change.</p>

    <div class="card">
      <label for="m">Message</label>
      <textarea id="m" [ngModel]="message()" (ngModelChange)="message.set($event)" style="min-height:90px"></textarea>
      <div class="grid2">
        <div>
          <h2>Rule-based</h2>
          <p [class]="rules().spam ? 'bad' : 'ok'"><strong>{{ rules().spam ? 'Looks like a scam' : 'No rule fired' }}</strong></p>
          @for (h of rules().hits; track h) { <p class="muted">Rule: {{ h }}</p> }
        </div>
        <div>
          <h2>Learned from examples</h2>
          <p [class]="learned().spam ? 'bad' : 'ok'"><strong>{{ learned().spam ? 'Looks like a scam' : 'Looks normal' }}</strong> ({{ percent() }}% scam)</p>
          @for (t of learned().top; track t.word) { <p class="muted">"{{ t.word }}" pushes towards {{ t.weight > 0 ? 'scam' : 'normal' }} ({{ t.weight.toFixed(1) }})</p> }
        </div>
      </div>
    </div>

    <div class="card">
      <h2>Training examples ({{ examples().length }})</h2>
      <label for="n">Add an example</label>
      <input id="n" [(ngModel)]="newText" placeholder="Type a message..." />
      <button (click)="add(true)" [disabled]="!newText.trim()">Add as scam</button>
      <button class="secondary" (click)="add(false)" [disabled]="!newText.trim()">Add as normal</button>
      <table>
        <tbody>
          @for (e of examples(); track $index) {
            <tr><td [class]="e.spam ? 'bad' : 'ok'">{{ e.spam ? 'scam' : 'normal' }}</td><td>{{ e.text }}</td><td><button class="danger" (click)="remove($index)">x</button></td></tr>
          }
        </tbody>
      </table>
    </div>
  `,
})
export class SpamPage {
  message = signal('Hurry! Pay a registration fee today and earn 3000 per day from home');
  examples = signal<Example[]>([...startExamples]);
  newText = '';

  rules = computed(() => ruleVerdict(this.message()));
  model = computed(() => new NaiveBayes(this.examples()));
  learned = computed(() => this.model().classify(this.message()));
  percent = computed(() => Math.round(this.learned().probSpam * 100));

  add(spam: boolean) {
    this.examples.update((list) => [{ text: this.newText.trim(), spam }, ...list]);
    this.newText = '';
  }

  remove(i: number) {
    this.examples.update((list) => list.filter((_, j) => j !== i));
  }
}

// The small amount of maths that appears again and again in AI.

export const parseVector = (text: string): number[] =>
  text.split(/[,\s]+/).filter(Boolean).map(Number).filter((n) => Number.isFinite(n));

export const dot = (a: number[], b: number[]) => a.reduce((sum, x, i) => sum + x * (b[i] ?? 0), 0);

export const norm = (a: number[]) => Math.sqrt(dot(a, a)); // the length of the vector

// 1 = same direction, 0 = unrelated (at right angles), -1 = opposite.
export function cosine(a: number[], b: number[]) {
  const d = norm(a) * norm(b);
  return d === 0 ? 0 : dot(a, b) / d;
}

export const mean = (xs: number[]) => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : 0);

export function stdDev(xs: number[]) {
  const m = mean(xs);
  return xs.length ? Math.sqrt(mean(xs.map((x) => (x - m) ** 2))) : 0; // how spread out the numbers are
}

// Turns any list of scores into probabilities that add up to 1.
export function softmax(xs: number[]) {
  if (!xs.length) return [];
  const max = Math.max(...xs); // subtracting the max keeps the numbers from getting too big
  const exps = xs.map((x) => Math.exp(x - max));
  const sum = exps.reduce((s, x) => s + x, 0);
  return exps.map((e) => e / sum);
}

// One step of "learning": move a number a little downhill on y = (x - target)^2.
export function gradientSteps(start: number, target: number, rate: number, steps: number) {
  const path = [start];
  let x = start;
  for (let i = 0; i < steps; i++) {
    x -= rate * 2 * (x - target); // 2 * (x - target) is the slope of the curve at x
    path.push(x);
  }
  return path;
}

import { Component, computed, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { cosine, dot, gradientSteps, mean, norm, parseVector, softmax, stdDev } from '../lib/math';

@Component({
  selector: 'app-vectors',
  imports: [FormsModule],
  template: `
    <h1>The maths of AI, one number at a time</h1>
    <p class="hint">Change any box and every result updates. Try to predict the answer before you look.</p>

    <div class="card">
      <h2>Vectors and similarity</h2>
      <div class="grid2">
        <div><label for="a">Vector A</label><input id="a" [ngModel]="a()" (ngModelChange)="a.set($event)" /></div>
        <div><label for="b">Vector B</label><input id="b" [ngModel]="b()" (ngModelChange)="b.set($event)" /></div>
      </div>
      <table><tbody>
        <tr><td>Length of A</td><td>{{ norm(va()).toFixed(3) }}</td></tr>
        <tr><td>Dot product A . B</td><td>{{ dot(va(), vb()).toFixed(3) }}</td></tr>
        <tr><td>Cosine similarity</td><td><strong>{{ cosine(va(), vb()).toFixed(3) }}</strong></td></tr>
      </tbody></table>
      <p class="muted">Try A = 1, 2 and B = 2, 4 (same direction), then B = 2, -1 (right angle), then B = -1, -2 (opposite).</p>
    </div>

    <div class="card">
      <h2>Averages and spread</h2>
      <label for="n">Numbers (for example monthly salaries or response times)</label>
      <input id="n" [ngModel]="nums()" (ngModelChange)="nums.set($event)" />
      <table><tbody>
        <tr><td>Average</td><td>{{ mean(vn()).toFixed(2) }}</td></tr>
        <tr><td>Standard deviation (spread)</td><td>{{ stdDev(vn()).toFixed(2) }}</td></tr>
      </tbody></table>
    </div>

    <div class="card">
      <h2>Softmax: scores to probabilities</h2>
      <label for="s">Scores</label>
      <input id="s" [ngModel]="scores()" (ngModelChange)="scores.set($event)" />
      <table><tbody>
        @for (p of probs(); track $index) {
          <tr><td>Score {{ vs()[$index] }}</td><td>{{ (p * 100).toFixed(1) }}%</td></tr>
        }
      </tbody></table>
      <p class="muted">The probabilities always add up to 100%. Models use this to turn scores into a choice of the next word.</p>
    </div>

    <div class="card">
      <h2>Learning is walking downhill</h2>
      <div class="grid2">
        <div><label for="r">Step size: {{ rate() }}</label><input id="r" type="range" min="0.01" max="1.05" step="0.01" [ngModel]="rate()" (ngModelChange)="rate.set(+$event)" /></div>
        <div><label for="t">Target value: {{ target() }}</label><input id="t" type="range" min="-10" max="10" step="1" [ngModel]="target()" (ngModelChange)="target.set(+$event)" /></div>
      </div>
      <p>Start at 0, aim for {{ target() }}. After 8 steps: <strong>{{ path()[8].toFixed(3) }}</strong></p>
      <p class="muted">Path: {{ pathText() }}</p>
      <p class="muted">A tiny step crawls. A step of 0.5 lands on the target at once. A step above 1 overshoots more and more, and the number flies away.</p>
    </div>
  `,
})
export class VectorsPage {
  a = signal('1, 2, 3');
  b = signal('2, 4, 6');
  nums = signal('25000, 27000, 26000, 90000, 24000');
  scores = signal('2.0, 1.0, 0.1');
  rate = signal(0.3);
  target = signal(6);

  va = computed(() => parseVector(this.a()));
  vb = computed(() => parseVector(this.b()));
  vn = computed(() => parseVector(this.nums()));
  vs = computed(() => parseVector(this.scores()));
  probs = computed(() => softmax(this.vs()));
  path = computed(() => gradientSteps(0, this.target(), this.rate(), 8));
  pathText = computed(() => this.path().map((x) => x.toFixed(2)).join(' → '));

  dot = dot;
  norm = norm;
  cosine = cosine;
  mean = mean;
  stdDev = stdDev;
}

// A seeded random number generator. The same seed always gives the same numbers,
// which makes experiments repeatable: you can compare two settings fairly.
export function makeRng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296; // a number from 0 up to (not including) 1
  };
}

export function shuffle<T>(items: T[], rng: () => number): T[] {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

import { makeRng, shuffle } from './rng';

// A candidate described by two numbers, and whether the recruiter shortlisted them.
export type Person = { years: number; skills: number; shortlisted: boolean };

// Make an imaginary but sensible dataset: more experience and more matching skills usually means shortlisted,
// but with some randomness, because real hiring is never perfectly predictable.
export function makeData(count: number, seed: number, noise = 0.25): Person[] {
  const rng = makeRng(seed);
  return Array.from({ length: count }, () => {
    const years = Math.round(rng() * 150) / 10; // 0 to 15 years
    const skills = Math.round(rng() * 10); // 0 to 10 matching skills
    const score = 0.5 * (years / 15) + 0.5 * (skills / 10) + (rng() - 0.5) * noise * 2;
    return { years, skills, shortlisted: score > 0.5 };
  });
}

// Training data teaches the model. Test data is kept hidden and used only to check it.
export function split(data: Person[], testShare: number, seed: number) {
  const mixed = shuffle(data, makeRng(seed));
  const testSize = Math.max(1, Math.round(mixed.length * testShare));
  return { test: mixed.slice(0, testSize), train: mixed.slice(testSize) };
}

const distance = (a: Person, b: Person) => Math.hypot((a.years - b.years) / 15, (a.skills - b.skills) / 10);

// k-nearest neighbours: look at the k most similar people in the training data and let them vote.
export function predict(train: Person[], who: Pick<Person, 'years' | 'skills'>, k: number): boolean {
  const near = train
    .map((p) => ({ p, d: distance(p, who as Person) }))
    .sort((x, y) => x.d - y.d)
    .slice(0, Math.max(1, k));
  const yes = near.filter((n) => n.p.shortlisted).length;
  return yes * 2 > near.length;
}

export function evaluate(train: Person[], test: Person[], k: number) {
  const matrix = { tp: 0, fp: 0, tn: 0, fn: 0 };
  for (const p of test) {
    const guess = predict(train, p, k);
    if (guess && p.shortlisted) matrix.tp++;
    else if (guess && !p.shortlisted) matrix.fp++;
    else if (!guess && !p.shortlisted) matrix.tn++;
    else matrix.fn++;
  }
  const total = test.length || 1;
  const accuracy = (matrix.tp + matrix.tn) / total;
  const precision = matrix.tp / ((matrix.tp + matrix.fp) || 1);
  const recall = matrix.tp / ((matrix.tp + matrix.fn) || 1);
  return { matrix, accuracy, precision, recall };
}

import { Component, computed, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { evaluate, makeData, split } from '../lib/knn';

@Component({
  selector: 'app-classifier',
  imports: [FormsModule],
  template: `
    <h1>Train, test and overfit</h1>
    <p class="hint">A model learns to guess who gets shortlisted from years of experience and matching skills. Watch the gap between its score on data it has seen and data it has not.</p>

    <div class="card">
      <div class="grid2">
        <div><label for="k">Neighbours that vote (k): {{ k() }}</label><input id="k" type="range" min="1" max="31" step="2" [ngModel]="k()" (ngModelChange)="k.set(+$event)" /></div>
        <div><label for="t">Share kept for testing: {{ (testShare() * 100).toFixed(0) }}%</label><input id="t" type="range" min="0.1" max="0.5" step="0.05" [ngModel]="testShare()" (ngModelChange)="testShare.set(+$event)" /></div>
      </div>
      <div class="grid2">
        <div><label for="n">Noise in the data: {{ noise() }}</label><input id="n" type="range" min="0" max="0.6" step="0.05" [ngModel]="noise()" (ngModelChange)="noise.set(+$event)" /></div>
        <div><label for="s">Random seed: {{ seed() }}</label><input id="s" type="range" min="1" max="20" step="1" [ngModel]="seed()" (ngModelChange)="seed.set(+$event)" /></div>
      </div>
    </div>

    <div class="card">
      <h2>Results ({{ parts().train.length }} training, {{ parts().test.length }} test)</h2>
      <table><tbody>
        <tr><td>Accuracy on training data (seen)</td><td><strong>{{ pct(trainResult().accuracy) }}</strong></td></tr>
        <tr><td>Accuracy on test data (not seen)</td><td><strong>{{ pct(testResult().accuracy) }}</strong></td></tr>
        <tr><td>Gap</td><td [class]="gap() > 0.12 ? 'bad' : 'ok'">{{ pct(gap()) }} {{ gap() > 0.12 ? '(overfitting)' : '' }}</td></tr>
      </tbody></table>
      <h2>Confusion matrix (test data)</h2>
      <table><thead><tr><th></th><th>Predicted: shortlisted</th><th>Predicted: not</th></tr></thead><tbody>
        <tr><td>Really shortlisted</td><td>{{ testResult().matrix.tp }}</td><td>{{ testResult().matrix.fn }}</td></tr>
        <tr><td>Really not</td><td>{{ testResult().matrix.fp }}</td><td>{{ testResult().matrix.tn }}</td></tr>
      </tbody></table>
      <p class="muted">Precision {{ pct(testResult().precision) }}: when it says shortlisted, how often is it right. Recall {{ pct(testResult().recall) }}: of the people really shortlisted, how many it found.</p>
      <p class="muted">Try k = 1. It memorises the training data (100% on seen data) but does worse on new data. A larger k smooths out the noise.</p>
    </div>
  `,
})
export class ClassifierPage {
  k = signal(1);
  testShare = signal(0.3);
  noise = signal(0.25);
  seed = signal(7);

  data = computed(() => makeData(200, this.seed(), this.noise()));
  parts = computed(() => split(this.data(), this.testShare(), this.seed()));
  trainResult = computed(() => evaluate(this.parts().train, this.parts().train, this.k()));
  testResult = computed(() => evaluate(this.parts().train, this.parts().test, this.k()));
  gap = computed(() => Math.max(0, this.trainResult().accuracy - this.testResult().accuracy));

  pct = (x: number) => `${(x * 100).toFixed(1)}%`;
}

import { makeRng } from './rng';

// A tiny neural network: layers of simple units. Each unit adds up its inputs times weights,
// adds a bias, and squashes the result between 0 and 1 (the sigmoid function).
export type Net = { sizes: number[]; w: number[][][]; b: number[][] }; // w[layer][unit][input]

const sigmoid = (x: number) => 1 / (1 + Math.exp(-x));

export function createNet(hidden: number, seed: number): Net {
  const rng = makeRng(seed);
  const sizes = hidden > 0 ? [2, hidden, 1] : [2, 1]; // hidden = 0 means no hidden layer at all
  const w: number[][][] = [];
  const b: number[][] = [];
  for (let l = 1; l < sizes.length; l++) {
    w.push(Array.from({ length: sizes[l]! }, () => Array.from({ length: sizes[l - 1]! }, () => (rng() - 0.5) * 2)));
    b.push(Array.from({ length: sizes[l]! }, () => (rng() - 0.5) * 2));
  }
  return { sizes, w, b };
}

export function forward(net: Net, input: number[]): number[][] {
  const acts = [input];
  for (let l = 0; l < net.w.length; l++) {
    const prev = acts[l]!;
    acts.push(net.w[l]!.map((weights, u) => sigmoid(weights.reduce((s, wt, i) => s + wt * prev[i]!, net.b[l]![u]!))));
  }
  return acts;
}

export const predict = (net: Net, input: number[]) => forward(net, input).at(-1)![0]!;

export type Sample = { input: number[]; target: number };

// Training = repeat: make a guess, measure the error, nudge every weight a little to reduce the error.
// The nudging rule is called backpropagation.
export function train(net: Net, data: Sample[], epochs: number, rate: number) {
  const history: number[] = [];
  for (let e = 0; e < epochs; e++) {
    let loss = 0;
    for (const { input, target } of data) {
      const acts = forward(net, input);
      const out = acts.at(-1)![0]!;
      loss += (out - target) ** 2;
      // delta = how much each unit contributed to the error
      let delta = [(out - target) * out * (1 - out)];
      for (let l = net.w.length - 1; l >= 0; l--) {
        const prev = acts[l]!;
        const nextDelta = prev.map((a, i) => a * (1 - a) * delta.reduce((s, d, u) => s + d * net.w[l]![u]![i]!, 0));
        for (let u = 0; u < delta.length; u++) {
          for (let i = 0; i < prev.length; i++) net.w[l]![u]![i]! -= rate * delta[u]! * prev[i]!;
          net.b[l]![u]! -= rate * delta[u]!;
        }
        delta = nextDelta;
      }
    }
    if (e % Math.max(1, Math.floor(epochs / 50)) === 0 || e === epochs - 1) history.push(loss / data.length);
  }
  return history;
}

export const XOR: Sample[] = [
  { input: [0, 0], target: 0 },
  { input: [0, 1], target: 1 },
  { input: [1, 0], target: 1 },
  { input: [1, 1], target: 0 },
];

import { Component, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { XOR, createNet, predict, train, type Net } from '../lib/nn';

@Component({
  selector: 'app-neural',
  imports: [FormsModule],
  template: `
    <h1>A neural network in your browser</h1>
    <p class="hint">XOR means "one or the other, but not both". A single layer of units cannot learn it. Add a hidden layer and it can. Train and see.</p>

    <div class="card">
      <div class="grid2">
        <div><label for="h">Hidden units: {{ hidden() }}</label><input id="h" type="range" min="0" max="8" step="1" [ngModel]="hidden()" (ngModelChange)="hidden.set(+$event)" /></div>
        <div><label for="e">Training rounds: {{ epochs() }}</label><input id="e" type="range" min="500" max="10000" step="500" [ngModel]="epochs()" (ngModelChange)="epochs.set(+$event)" /></div>
      </div>
      <button (click)="run()" [disabled]="busy()">{{ busy() ? 'Training...' : 'Train from scratch' }}</button>
    </div>

    @if (result(); as r) {
      <div class="card">
        <h2>Results with {{ r.hidden }} hidden unit(s)</h2>
        <p>Final error: <strong [class]="r.loss < 0.02 ? 'ok' : 'bad'">{{ r.loss.toFixed(4) }}</strong> {{ r.loss < 0.02 ? '(learned it)' : '(did not learn it)' }}</p>
        <table>
          <thead><tr><th>Input</th><th>Should be</th><th>Network says</th></tr></thead>
          <tbody>
            @for (row of r.rows; track $index) {
              <tr><td>{{ row.input }}</td><td>{{ row.target }}</td><td [class]="row.ok ? 'ok' : 'bad'">{{ row.out.toFixed(2) }}</td></tr>
            }
          </tbody>
        </table>
        <p class="muted">Error over time (each bar is one checkpoint, taller means more wrong):</p>
        <div class="spark">@for (v of r.history; track $index) { <span [style.height.px]="Math.max(2, v * 160)"></span> }</div>
      </div>
    }
  `,
  styles: [`.spark { display:flex; align-items:flex-end; gap:2px; height:80px; } .spark span { flex:1; background:#4f46e5; border-radius:2px 2px 0 0; }`],
})
export class NeuralPage {
  Math = Math;
  hidden = signal(4);
  epochs = signal(4000);
  busy = signal(false);
  result = signal<{ hidden: number; loss: number; history: number[]; rows: { input: string; target: number; out: number; ok: boolean }[] } | null>(null);

  run() {
    this.busy.set(true);
    // setTimeout lets the button update before the browser is busy with training
    setTimeout(() => {
      const net: Net = createNet(this.hidden(), 3);
      const history = train(net, XOR, this.epochs(), 0.8);
      const rows = XOR.map((s) => {
        const out = predict(net, s.input);
        return { input: s.input.join(', '), target: s.target, out, ok: Math.round(out) === s.target };
      });
      this.result.set({ hidden: this.hidden(), loss: history.at(-1) ?? 1, history, rows });
      this.busy.set(false);
    }, 20);
  }
}

import { makeRng } from './rng';

// A Markov chain is the simplest text generator: it only remembers the last few words.
// "order" is how many words it remembers. Order 1 = the last word. Order 2 = the last two words.
export type Chain = { order: number; next: Map<string, string[]>; starts: string[] };

const tokens = (text: string) => text.replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);

export function buildChain(text: string, order: number): Chain {
  const words = tokens(text);
  const next = new Map<string, string[]>();
  const starts: string[] = [];
  for (let i = 0; i + order < words.length; i++) {
    const key = words.slice(i, i + order).join(' ');
    if (i === 0 || /[.!?]$/.test(words[i - 1]!)) starts.push(key); // a good place to begin: the start of a sentence
    next.set(key, [...(next.get(key) ?? []), words[i + order]!]);
  }
  return { order, next, starts };
}

// Pick a start, then repeat: look at the last words, choose one of the words that followed them in the text.
export function generate(chain: Chain, count: number, seed: number): string {
  const rng = makeRng(seed);
  if (!chain.starts.length) return '';
  let current = chain.starts[Math.floor(rng() * chain.starts.length)]!.split(' ');
  const out = [...current];
  while (out.length < count) {
    const options = chain.next.get(current.join(' '));
    if (!options?.length) {
      current = chain.starts[Math.floor(rng() * chain.starts.length)]!.split(' '); // dead end: start a new sentence
      out.push(...current);
    } else {
      const word = options[Math.floor(rng() * options.length)]!;
      out.push(word);
      current = [...current.slice(1), word];
    }
  }
  return out.slice(0, count).join(' ');
}

// How much of the output is copied straight from the source? (runs of 4 words that appear in it)
export function copiedShare(source: string, output: string) {
  const src = tokens(source).join(' ');
  const out = tokens(output);
  if (out.length < 4) return 0;
  let hit = 0;
  for (let i = 0; i + 4 <= out.length; i++) if (src.includes(out.slice(i, i + 4).join(' '))) hit++;
  return hit / (out.length - 3);
}

